// 1. The RBAC Middleware Factory
// It takes the role we WANT to require, and returns a middleware function
const authorize = (requiredRole) => {
  return (req, res, next) => {

    // Assume req.user was populated by a previous JWT authentication middleware
    const user = req.user;

    if (!user) {
      return console.log("401 Unauthorized: Please log in.");
    }

    if (user.role !== requiredRole) {
      return console.log(`403 Forbidden: You are a ${user.role}, but this requires ${requiredRole}!`);
    }

    console.log("Access Granted! Proceeding to route...");
    next();
  };
};

// 2. Simulated Requests
const mockNext = () => console.log("--> Reached Controller Logic\n");

console.log("--- Alice (Admin) requesting Dashboard ---");
const reqAlice = { user: { name: "Alice", role: "admin" } };
authorize('admin')(reqAlice, {}, mockNext);

console.log("--- Bob (User) requesting Dashboard ---");
const reqBob = { user: { name: "Bob", role: "user" } };
authorize('admin')(reqBob, {}, mockNext);
